contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "not enough balance");
        uint beforeTest = address(this).balance;

        c.sendMoney(address(this), value, ""); if (__ESBMC_reverted()) return;

        assert(address(this).balance == beforeTest + value);
    }
}

